<div class="admin-title"><div><span class="eyebrow">VALUE, DELIVERED SECURELY</span><h1><?= e($title) ?></h1><p><?= t('Redeem codes are random, single-use and stored only as keyed hashes.') ?></p></div></div><?php if (!empty($_SESSION['issued_codes'])): $codes=$_SESSION['issued_codes'];unset($_SESSION['issued_codes']); ?><section class="panel section"><div class="alert warning"><?= t('Copy these codes now. Plaintext will not be displayed again after this page.') ?></div><pre class="code-box" id="issued-codes"><?= e(implode("\n",$codes)) ?></pre><button class="btn secondary" data-copy-target="#issued-codes"><?= icon('download') ?><?= t('Copy all codes') ?></button></section><?php endif ?><div class="two-column"><section class="panel"><h2><?= t('Generate a batch') ?></h2><?= form_start('admin_vouchers') ?><?php field('label','Batch label','','text',['required'=>'required']);select_field('kind','Redeem type',options(['balance','points','tokens','membership']));field('amount','Amount (CNY, points, tokens or VIP days)','','number',['min'=>'0.01','step'=>'0.01','required'=>'required']);field('count','Number of codes',10,'number',['min'=>'1','max'=>'100','required'=>'required']);field('expires_at','Expiry',date('Y-m-d\TH:i',time()+2592000),'datetime-local',['required'=>'required']);button('Generate codes','full','gift'); ?></form></section><section class="panel"><h2><?= t('Recent batches') ?></h2><div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th><?= t('Label') ?></th><th><?= t('Value') ?></th><th><?= t('Redeemed by') ?></th></tr></thead><tbody><?php foreach ($a->db->all('SELECT id,label,kind,amount,redeemed_by,expires_at FROM cy_vouchers ORDER BY id DESC LIMIT 100') as $row): ?><tr><td>#<?= (int)$row['id'] ?></td><td><?= e($row['label']) ?><small><?= dt((int)$row['expires_at']) ?></small></td><td><?= $row['kind']==='membership'?(int)$row['amount'].' '.t('VIP days'):e(price((int)$row['amount'],$row['kind'])) ?></td><td><?= $row['redeemed_by']?'#'.(int)$row['redeemed_by']:t('Not redeemed') ?></td></tr><?php endforeach ?></tbody></table></div><p class="hint"><?= t('Latest 100 codes. Issuing a code does not itself credit an account.') ?></p></section></div>
